#!/bin/bash
set -euo pipefail
test -f /.dockerenv
test "${VAULT443_PACKAGE_TEST:-}" = 1
test "${VAULT443_E2E_ISOLATED:-}" = 1
test "$(cat /proc/1/comm)" = systemd
export VAULT443_WORKVPN_E2E=1
if [ ! -f /fixture/work/client-1.ovpn ]; then /bin/bash /src/tests/e2e/workvpn-fixture.sh; fi
# All credentials are generated by the disposable fixture. Never read a home
# directory or disable the production D-Bus caller checks for a package test.
systemctl stop vault443.service
VAULT443_PACKAGE_WORK_SEED=1 /src/.cache/workvpn-e2e.test -test.run '^TestPackageWorkProfiles$' -test.v
cp /var/lib/vault443/work-vpn.json /tmp/work-state-before.json
systemctl start vault443.service
python3 /src/tests/package-workvpn-check.py connected
old_pid=$(systemctl show -p MainPID --value vault443.service)
python3 /src/tests/package-workvpn-check.py monitor >/tmp/work-guard-monitor.log 2>&1 &
monitor=$!
for _ in $(seq 1 50); do test ! -f /tmp/work-monitor-ready || break; sleep .1; done
test -f /tmp/work-monitor-ready
kill -KILL "$old_pid"
for _ in $(seq 1 100); do
  new_pid=$(systemctl show -p MainPID --value vault443.service)
  if [ "$new_pid" != 0 ] && [ "$new_pid" != "$old_pid" ]; then break; fi
  sleep .1
done
python3 /src/tests/package-workvpn-check.py connected
touch /tmp/work-monitor-stop
wait "$monitor"
cat /tmp/work-guard-monitor.log
systemctl restart vault443.service
python3 /src/tests/package-workvpn-check.py connected
python3 /src/tests/package-network-check.py connected
python3 - <<'PY'
import json, os
from pathlib import Path
before=json.loads(Path('/tmp/work-state-before.json').read_text())
after=json.loads(Path('/var/lib/vault443/work-vpn.json').read_text())
assert before==after, 'restart changed private work profiles or desired sessions'
assert os.stat('/var/lib/vault443/work-vpn.json').st_mode & 0o777 == 0o600
PY
echo 'PASS: hardened systemd OpenVPN helper, two work tunnels plus VLESS, crash/restart recovery and continuous work-route protection'
